/**
 * 设置体验候选：只负责 Playground 的信息架构和组合态验证。
 *
 * 背景：正式 Settings 承载真实设置读取、自动保存、权限确认和敏感值脱敏，
 *       不能为了试验新的 IA 直接在生产面板上改默认行为。
 * 设计意图：用与生产能力对齐、但完全由 Renderer fixture 驱动的候选，先验证
 *       用户能否理解“日常设置 / 高级设置 / 低频入口”的边界。
 * 关键约束：不得调用 window.electronAPI，不展示真实 Key、MCP secret、权限规则或路径；
 *       所有开关、折叠、连接状态和输入都只存在于当前 Playground 会话。
 */
import { useEffect, useState, type ReactNode } from 'react'
import { Brain, Check, ChevronRight, CircleHelp, Cloud, Database, Download, Eye, Heart, KeyRound, Link2, LockKeyhole, Palette, Plug, Save, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Upload, UserRound, Wrench, Activity, Gauge, Plus, Server, ListChecks } from 'lucide-react'
import { DESIGN_THEME_ASSETS, FONT_SCALE_ASSETS } from '../../shared/design-asset-registry'
import { PROVIDER_PRESET_GROUPS } from '../../shared/provider-presets'

export type SettingsCandidateSection = 'appearance' | 'companion' | 'model' | 'memory' | 'data' | 'permissions' | 'extensions' | 'about'

export interface SettingsExperienceCandidateProps {
  companionDetail?: ReactNode
  initialSection?: SettingsCandidateSection
  onOpenMemory?: () => void
  onOpenRoleShelf?: () => void
}

interface SettingCardProps { children: ReactNode; testId?: string }
interface SettingRowProps { children: ReactNode; description?: string; icon?: ReactNode; label: string; scope?: string; stacked?: boolean }
interface CandidateSwitchProps { checked: boolean; description: string; label: string; onChange: (checked: boolean) => void; scope?: string; testId: string }

export const SETTINGS_CANDIDATE_NAV_GROUPS: Array<{ group: string; items: Array<{ id: SettingsCandidateSection; label: string; icon: ReactNode }> }> = [
  { group: '日常', items: [
    { id: 'appearance' as const, label: '外观与界面', icon: <Palette size={15} strokeWidth={1.8} /> },
    { id: 'companion' as const, label: '伙伴与相处', icon: <Heart size={15} strokeWidth={1.8} /> },
    { id: 'model' as const, label: '模型', icon: <Cloud size={15} strokeWidth={1.8} /> },
    { id: 'memory' as const, label: '记忆与相处', icon: <Brain size={15} strokeWidth={1.8} /> },
    { id: 'data' as const, label: '数据与隐私', icon: <Database size={15} strokeWidth={1.8} /> },
  ] },
  { group: '高级', items: [
    { id: 'permissions' as const, label: '权限与自动化', icon: <ShieldCheck size={15} strokeWidth={1.8} /> },
    { id: 'extensions' as const, label: '扩展与工具', icon: <Plug size={15} strokeWidth={1.8} /> },
  ] },
]

const NAV_ITEMS: Array<{ id: SettingsCandidateSection; label: string; icon: ReactNode }> = SETTINGS_CANDIDATE_NAV_GROUPS.flatMap((group) => group.items)

function SettingCard({ children, testId }: SettingCardProps) {
  return <section className="rounded-[var(--radius-lg)] border p-4 sm:p-5" data-testid={testId} style={{ borderColor: 'var(--card-border)', background: 'var(--card-bg)' }}>{children}</section>
}

function ScopeBadge({ label }: { label: string }) {
  return <span className="shrink-0 rounded-full border px-2 py-0.5 text-[9px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>{label}</span>
}

function SettingRow({ children, description, icon, label, scope, stacked = false }: SettingRowProps) {
  return <div className={`flex gap-4 ${stacked ? 'flex-col' : 'items-start justify-between'}`}>
    <div className="flex min-w-0 gap-3">
      {icon && <span className="mt-0.5 shrink-0" style={{ color: 'var(--accent-fg)' }} aria-hidden="true">{icon}</span>}
      <div className="min-w-0"><div className="flex items-center gap-2 text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}><span>{label}</span>{scope && <ScopeBadge label={scope} />}</div>{description && <p className="mt-1 max-w-xl text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>{description}</p>}</div>
    </div>
    <div className={stacked ? '' : 'shrink-0'}>{children}</div>
  </div>
}

function CandidateSwitch({ checked, description, label, onChange, scope, testId }: CandidateSwitchProps) {
  return <button type="button" role="switch" aria-checked={checked} aria-label={label} onClick={() => onChange(!checked)} className="flex w-full items-center justify-between gap-4 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)', background: checked ? 'var(--accent-subtle)' : 'transparent' }} data-testid={testId}>
    <span className="min-w-0"><span className="flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{scope && <ScopeBadge label={scope} />}</span><span className="mt-0.5 block text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{description}</span></span>
    <span className="relative h-5 w-9 shrink-0 rounded-full transition" style={{ background: checked ? 'var(--accent-emphasis)' : 'var(--bg-tertiary)' }} aria-hidden="true"><span className="absolute top-0.5 h-4 w-4 rounded-full bg-white shadow-sm transition" style={{ left: checked ? 'calc(100% - 1.125rem)' : '0.125rem' }} /></span>
  </button>
}

function CandidatePageHeader({ description, icon, title }: { description: string; icon: ReactNode; title: string }) {
  return <header className="mb-5 flex items-start justify-between gap-4"><div className="min-w-0"><div className="mb-2 flex items-center gap-2 text-[10px] font-semibold tracking-[0.16em]" style={{ color: 'var(--accent-fg)' }}><span aria-hidden="true">{icon}</span>设置样张</div><h2 className="text-xl font-semibold tracking-tight" style={{ color: 'var(--text-primary)' }}>{title}</h2><p className="mt-1 max-w-2xl text-[12px] leading-5" style={{ color: 'var(--text-muted)' }}>{description}</p></div><span className="shrink-0 rounded-full border px-2.5 py-1 text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-muted)' }}>仅供预览</span></header>
}

function AppearancePage({ activeTheme, fontScale, onFontScaleChange, onThemeChange }: { activeTheme: string; fontScale: string; onFontScaleChange: (value: string) => void; onThemeChange: (value: string) => void }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-appearance"><CandidatePageHeader icon={<Palette size={14} />} title="外观与界面" description="调整你每天看见和使用的感觉；没有接入的能力不会伪装成开关。" /><SettingCard><SettingRow scope="本机" label="界面语言" description="当前只提供简体中文，语言切换接入前保持为说明状态。" icon={<CircleHelp size={15} />}><span className="rounded-full border px-2.5 py-1 text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }}>简体中文</span></SettingRow></SettingCard><SettingCard testId="settings-candidate-theme-card"><div className="mb-3 flex items-end justify-between gap-3"><div><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>主题</h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>先选气质，再看细节；主题来自正式设计资产。</p></div><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{DESIGN_THEME_ASSETS.find((theme) => theme.id === activeTheme)?.labelZh ?? activeTheme}</span></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{DESIGN_THEME_ASSETS.map((theme) => { const selected = activeTheme === theme.id; return <button key={theme.id} type="button" aria-pressed={selected} onClick={() => onThemeChange(theme.id)} className="rounded-[var(--radius-md)] border p-3 text-left transition" data-selected={selected ? 'true' : undefined} style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center gap-2"><span className="h-3 w-3 rounded-full border" style={{ background: theme.representativeColor, borderColor: 'var(--border-color)' }} /><span className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{theme.labelZh}</span>{selected && <Check size={13} className="ml-auto" style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{theme.descriptionZh}</div></button> })}</div></SettingCard><SettingCard><SettingRow scope="本机" label="字体大小" description="只影响本机界面字号；不改变内容本身。" icon={<Eye size={15} />} stacked><div className="grid gap-2 sm:grid-cols-3">{FONT_SCALE_ASSETS.map((scale) => { const selected = fontScale === scale.id; return <button key={scale.id} type="button" aria-pressed={selected} onClick={() => onFontScaleChange(scale.id)} className="rounded-[var(--radius-md)] border px-3 py-2 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{scale.labelZh}</div><div className="mt-0.5 text-[10px]" style={{ color: 'var(--text-muted)' }}>{scale.descriptionZh}</div></button> })}</div></SettingRow></SettingCard></div>
}

function CompanionPage({ momentTips, onMomentTipsChange, onOpenRoleShelf, onProactiveGreetingChange, proactiveGreeting, expertise, onExpertiseChange }: { momentTips: boolean; onMomentTipsChange: (value: boolean) => void; onOpenRoleShelf?: () => void; onProactiveGreetingChange: (value: boolean) => void; proactiveGreeting: boolean; expertise: string; onExpertiseChange: (value: string) => void }) {
  const answerOptions = [
    ['auto', '自动', '根据问题难度调整', '简单问题直接回答，复杂问题补充步骤。'],
    ['novice', '讲清楚一些', '多补充背景和步骤', '解释为什么这样做，再带你一步步完成。'],
    ['intermediate', '重点优先', '先结论，再补关键原因', '给出做法，同时保留必要注意事项。'],
    ['expert', '直接一点', '默认进入细节', '省略基础介绍，直接给方案、参数和边界。'],
  ] as const
  return <div className="space-y-4" data-testid="settings-candidate-section-companion"><CandidatePageHeader icon={<Heart size={14} />} title="伙伴与相处" description="调整伙伴和你说话、提醒以及回应你的方式。" /><SettingCard><SettingRow scope="伙伴" label="当前伙伴" description="朋友圈、衣柜和对话都会跟随当前主角。" icon={<UserRound size={15} />}><button type="button" onClick={onOpenRoleShelf} className="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-[11px] transition" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} data-testid="settings-candidate-open-role-shelf">小林 · 管理角色架 <ChevronRight size={12} /></button></SettingRow></SettingCard><SettingCard><SettingRow scope="伙伴" label="回答方式" description="你希望伙伴平时怎么回答你？" icon={<Eye size={15} />} stacked><div className="grid gap-2 sm:grid-cols-2">{answerOptions.map(([value, label, description, example]) => { const selected = expertise === value; return <button key={value} type="button" aria-pressed={selected} onClick={() => onExpertiseChange(value)} className="rounded-[var(--radius-md)] border px-3 py-2.5 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center justify-between gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{selected && <Check size={13} style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-secondary)' }}>{description}</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>例如：{example}</div></button> })}</div></SettingRow></SettingCard><SettingCard><div className="space-y-2" data-testid="settings-candidate-companion-controls"><CandidateSwitch checked={momentTips} scope="伙伴" label="生活动态提醒" description="有新的生活动态时，在应用内轻轻提醒你。" onChange={onMomentTipsChange} testId="settings-candidate-switch-moment-tips" />{momentTips && <div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="mb-2 text-[11px] font-medium" style={{ color: 'var(--text-secondary)' }}>提醒节奏</div><div className="grid gap-2 sm:grid-cols-3">{[['勿扰开始', '22:00'], ['勿扰结束', '08:00'], ['每日最多', '3 条']].map(([label, value]) => <div key={label} className="rounded-[var(--radius-sm)] border px-2.5 py-2" style={{ borderColor: 'var(--border-subtle)' }}><div className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{label}</div><div className="mt-1 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{value}</div></div>)}</div></div>}<CandidateSwitch checked={proactiveGreeting} scope="伙伴" label="主动问候" description="允许伙伴在合适的时机主动来打个招呼，默认保持关闭。" onChange={onProactiveGreetingChange} testId="settings-candidate-switch-proactive-greeting" /></div></SettingCard><SettingCard><SettingRow label="相处补充说明" description="告诉伙伴你希望长期保持的回应方式；这是当前样张中的临时输入。" icon={<Sparkles size={15} />} stacked><textarea aria-label="相处补充说明" defaultValue="当我把事情排得太满时，提醒我留一点空白。" rows={3} className="theme-input w-full resize-y rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /></SettingRow></SettingCard></div>
}

type ModelPurpose = 'primary' | 'auxiliary' | 'unused'

type ModelFixture = { id: string; enabled: boolean; purpose: ModelPurpose }
type ModelProfileFixture = { id: string; name: string; providerId: string; providerLabel: string; baseUrl: string; status: 'idle' | 'success' | 'error'; models: ModelFixture[] }

function createModelProfile(provider: { providerId: string; label: string; baseUrl: string }, index = 0): ModelProfileFixture {
  return {
    id: `model-profile-${provider.providerId}-${index}`,
    name: index === 0 ? `${provider.label} 主账号` : `${provider.label} 配置`,
    providerId: provider.providerId,
    providerLabel: provider.label,
    baseUrl: provider.baseUrl,
    status: 'idle',
    models: index === 0
      ? [{ id: 'account-model-id', enabled: true, purpose: 'primary' }, { id: 'account-aux-model-id', enabled: false, purpose: 'auxiliary' }]
      : [],
  }
}

function ModelPage({ modelStatus, onModelStatusChange, selectedProvider, onProviderChange }: { modelStatus: 'idle' | 'success' | 'error'; onModelStatusChange: (status: 'idle' | 'success' | 'error') => void; selectedProvider: string; onProviderChange: (provider: string) => void }) {
  const allProviders = PROVIDER_PRESET_GROUPS.flatMap((group) => group.items)
  const firstProvider = allProviders.find((provider) => provider.providerId === selectedProvider) ?? allProviders[0]
  const [profiles, setProfiles] = useState<ModelProfileFixture[]>(() => [createModelProfile(firstProvider)])
  const [expandedProfileId, setExpandedProfileId] = useState<string | null>(profiles[0]?.id ?? null)
  const [isAddingProfile, setIsAddingProfile] = useState(false)
  const [addStep, setAddStep] = useState<'source' | 'provider' | 'details'>('source')
  const [addSource, setAddSource] = useState<'official' | 'relay' | 'coding' | 'local' | 'custom'>('official')
  const [addProviderId, setAddProviderId] = useState('openrouter')
  const [newProfileName, setNewProfileName] = useState('')
  const [newBaseUrl, setNewBaseUrl] = useState('')
  const [newModelId, setNewModelId] = useState('')
  const [newModelPurpose, setNewModelPurpose] = useState<ModelPurpose>('primary')
  const [addingModelProfileId, setAddingModelProfileId] = useState<string | null>(null)
  const [modelDraftId, setModelDraftId] = useState('')
  const [modelDraftPurpose, setModelDraftPurpose] = useState<ModelPurpose>('auxiliary')
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [sessionBudget, setSessionBudget] = useState('0')
  const [dailyBudget, setDailyBudget] = useState('0')

  const selectedAddProvider = allProviders.find((provider) => provider.providerId === addProviderId) ?? allProviders[0]
  const providerOptions = addSource === 'relay'
    ? allProviders.filter((provider) => provider.group === '聚合与代理')
    : addSource === 'coding'
      ? allProviders.filter((provider) => provider.group === '编程套餐')
      : addSource === 'local'
        ? allProviders.filter((provider) => provider.group === '本地 / 自定义')
        : allProviders.filter((provider) => provider.group === '海外直连' || provider.group === '国内服务商')

  const openAddProfile = () => {
    setIsAddingProfile(true)
    setAddStep('source')
    setNewProfileName('')
    setNewBaseUrl('')
    setNewModelId('')
    setNewModelPurpose('primary')
  }

  const selectAddSource = (source: typeof addSource) => {
    setAddSource(source)
    if (source === 'custom') {
      setAddStep('details')
      setNewProfileName('自定义模型配置')
      setNewBaseUrl('')
      return
    }
    const provider = source === 'relay' ? allProviders.find((item) => item.providerId === 'openrouter') : providerOptions[0]
    if (provider) {
      setAddProviderId(provider.providerId)
      setNewProfileName(`${provider.label} 配置`)
      setNewBaseUrl(provider.baseUrl)
    }
    setAddStep('provider')
  }

  const selectAddProvider = (providerId: string) => {
    const provider = allProviders.find((item) => item.providerId === providerId)
    if (!provider) return
    setAddProviderId(provider.providerId)
    setNewProfileName(`${provider.label} 配置`)
    setNewBaseUrl(provider.baseUrl)
    setAddStep('details')
    onProviderChange(provider.providerId)
  }

  const finishAddProfile = () => {
    if (!newProfileName.trim() || !newBaseUrl.trim() || !newModelId.trim()) return
    const provider = selectedAddProvider ?? { providerId: 'custom', label: '自定义接口', baseUrl: newBaseUrl.trim() }
    const profile: ModelProfileFixture = {
      id: `model-profile-${Date.now()}`,
      name: newProfileName.trim(),
      providerId: provider.providerId,
      providerLabel: provider.label,
      baseUrl: newBaseUrl.trim(),
      status: 'idle',
      models: [{ id: newModelId.trim(), enabled: true, purpose: newModelPurpose }],
    }
    setProfiles((current) => [...current, profile])
    setExpandedProfileId(profile.id)
    setIsAddingProfile(false)
  }

  const setPreviewState = (state: 'empty' | 'one' | 'two') => {
    const first = createModelProfile(firstProvider)
    if (state === 'empty') {
      setProfiles([])
      setExpandedProfileId(null)
      return
    }
    if (state === 'one') {
      setProfiles([first])
      setExpandedProfileId(first.id)
      return
    }
    const relay = allProviders.find((provider) => provider.providerId === 'openrouter') ?? allProviders[1]
    const second = createModelProfile(relay, 1)
    second.name = '中转备用配置'
    second.models = [{ id: 'relay-model-id', enabled: true, purpose: 'auxiliary' }]
    setProfiles([first, second])
    setExpandedProfileId(first.id)
  }

  const updateProfile = (profileId: string, update: (profile: ModelProfileFixture) => ModelProfileFixture) => {
    setProfiles((current) => current.map((profile) => profile.id === profileId ? update(profile) : profile))
  }

  const toggleModel = (profileId: string, modelId: string) => {
    updateProfile(profileId, (profile) => ({ ...profile, models: profile.models.map((model) => model.id === modelId ? { ...model, enabled: !model.enabled } : model) }))
  }

  const updateModelPurpose = (profileId: string, modelId: string, purpose: ModelPurpose) => {
    updateProfile(profileId, (profile) => ({ ...profile, models: profile.models.map((model) => model.id === modelId ? { ...model, purpose } : model) }))
  }

  const finishAddModel = (profileId: string) => {
    if (!modelDraftId.trim()) return
    updateProfile(profileId, (profile) => ({ ...profile, models: [...profile.models, { id: modelDraftId.trim(), enabled: true, purpose: modelDraftPurpose }] }))
    setModelDraftId('')
    setModelDraftPurpose('auxiliary')
    setAddingModelProfileId(null)
  }

  return <div className="space-y-4" data-testid="settings-candidate-section-model">
    <CandidatePageHeader icon={<Cloud size={14} />} title="模型" description="先添加一个连接，再决定这个连接里的哪些模型参与工作。Provider 只提供入口，模型 ID 由你的账户决定。" />
    <SettingCard testId="settings-candidate-model-overview">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div className="flex min-w-0 items-start gap-3"><span className="mt-0.5 rounded-full p-2" style={{ background: 'var(--accent-subtle)', color: 'var(--accent-fg)' }}><Server size={15} /></span><div><div className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>已添加的模型配置</div><p className="mt-1 text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>{profiles.length === 0 ? '还没有配置，先添加一个连接才能开始使用模型。' : `当前有 ${profiles.length} 个连接配置；每个配置可以放入多个模型。`}</p></div></div><button type="button" onClick={openAddProfile} className="inline-flex shrink-0 items-center gap-1 rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-model-add"><Plus size={13} />添加模型配置</button></div>
      <div className="mt-3 flex flex-wrap items-center gap-1.5 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><span className="mr-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>样张状态</span><button type="button" onClick={() => setPreviewState('empty')} className="settings-option px-2 py-1 text-[10px]" data-testid="settings-candidate-model-state-empty">空态</button><button type="button" onClick={() => setPreviewState('one')} className="settings-option px-2 py-1 text-[10px]" data-testid="settings-candidate-model-state-one">一个配置</button><button type="button" onClick={() => setPreviewState('two')} className="settings-option px-2 py-1 text-[10px]" data-testid="settings-candidate-model-state-two">两个配置</button></div>
    </SettingCard>
    {isAddingProfile && <SettingCard testId="settings-candidate-model-add-panel"><div role="dialog" aria-label="添加模型配置"><div className="flex items-start justify-between gap-3"><div><div className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>添加模型配置</div><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>{addStep === 'source' ? '先选择连接来源。' : addStep === 'provider' ? '选择一个入口，名称和地址会带入下一步。' : '补充配置名称和一个模型 ID。'}</p></div><button type="button" onClick={() => setIsAddingProfile(false)} className="rounded-full px-2 py-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>取消</button></div>
      {addStep === 'source' && <div className="mt-4 grid gap-2 sm:grid-cols-2">{[['official', '官方服务', 'OpenAI、Anthropic、DeepSeek 等'], ['relay', '中转 / 聚合', '一个入口承载多个上游模型'], ['coding', '编程套餐', '面向编码任务的服务入口'], ['local', '本地模型', 'Ollama、LM Studio 等'], ['custom', '自定义接口', '填写自己的兼容地址']].map(([value, label, description]) => <button key={value} type="button" onClick={() => selectAddSource(value as typeof addSource)} className="rounded-[var(--radius-md)] border p-3 text-left" style={{ borderColor: 'var(--border-subtle)' }} data-testid={`settings-candidate-model-source-${value}`}><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{description}</div></button>)}</div>}
      {addStep === 'provider' && <div className="mt-4 space-y-3"><div className="flex items-center justify-between gap-3"><button type="button" onClick={() => setAddStep('source')} className="text-[10px]" style={{ color: 'var(--accent-fg)' }}>← 返回来源</button><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>{providerOptions.length} 个可选入口</span></div><div className="grid gap-2 sm:grid-cols-2">{providerOptions.map((provider) => <button key={provider.key} type="button" onClick={() => selectAddProvider(provider.providerId)} className="rounded-[var(--radius-md)] border p-3 text-left" style={{ borderColor: 'var(--border-subtle)' }} data-testid={`settings-candidate-model-provider-${provider.providerId}`}><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{provider.label}</div><div className="mt-1 truncate font-mono text-[10px]" title={provider.baseUrl} style={{ color: 'var(--text-muted)' }}>{provider.baseUrl}</div></button>)}</div></div>}
      {addStep === 'details' && <div className="mt-4 space-y-3"><div className="flex items-center justify-between gap-3"><button type="button" onClick={() => setAddStep(addSource === 'custom' ? 'source' : 'provider')} className="text-[10px]" style={{ color: 'var(--accent-fg)' }}>← 返回上一步</button><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>模型 ID 不由 Provider 代填</span></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>配置名称<input aria-label="新配置名称" value={newProfileName} onChange={(event) => setNewProfileName(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[11px] outline-none" placeholder="例如：工作账号" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>API Key<input aria-label="新配置 API Key" value="已安全保存" readOnly className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[11px] outline-none" /></label></div><label className="block text-[10px]" style={{ color: 'var(--text-secondary)' }}>Base URL<input aria-label="新配置 Base URL" value={newBaseUrl} onChange={(event) => setNewBaseUrl(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 font-mono text-[11px] outline-none" placeholder="https://example.com/v1" /></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>第一个模型 ID<input aria-label="新模型 ID" value={newModelId} onChange={(event) => setNewModelId(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 font-mono text-[11px] outline-none" placeholder="填写账户实际提供的模型 ID" /></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>用途<select aria-label="新模型用途" value={newModelPurpose} onChange={(event) => setNewModelPurpose(event.target.value as ModelPurpose)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[11px] outline-none"><option value="primary">主对话</option><option value="auxiliary">辅助任务</option><option value="unused">暂不使用</option></select></label></div><div className="flex justify-end"><button type="button" onClick={finishAddProfile} disabled={!newProfileName.trim() || !newBaseUrl.trim() || !newModelId.trim()} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium disabled:cursor-not-allowed disabled:opacity-50" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-model-finish-add">添加这个配置</button></div></div>}
      </div></SettingCard>}
    {profiles.length === 0 && <SettingCard testId="settings-candidate-model-empty"><div className="flex flex-col items-center justify-center px-5 py-12 text-center"><Cloud size={22} style={{ color: 'var(--text-muted)' }} /><div className="mt-3 text-[14px] font-medium" style={{ color: 'var(--text-primary)' }}>还没有模型配置</div><p className="mt-1 max-w-sm text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>添加一个 Provider 或自定义接口，再把账户提供的模型 ID 放进来。</p><button type="button" onClick={openAddProfile} className="mt-4 rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }}>添加第一个模型配置</button></div></SettingCard>}
    {profiles.length > 0 && <SettingCard testId="settings-candidate-model-profiles"><div className="space-y-2">{profiles.map((profile) => { const expanded = expandedProfileId === profile.id; const status = profile.id === profiles[0]?.id ? modelStatus : profile.status; const enabledCount = profile.models.filter((model) => model.enabled).length; return <div key={profile.id} className="rounded-[var(--radius-md)] border" style={{ borderColor: expanded ? 'var(--accent)' : 'var(--border-subtle)', background: expanded ? 'var(--accent-subtle)' : 'transparent' }}><button type="button" onClick={() => setExpandedProfileId(expanded ? null : profile.id)} aria-expanded={expanded} className="flex w-full items-start justify-between gap-3 p-3 text-left" data-testid={`settings-candidate-model-profile-${profile.providerId}`}><div className="flex min-w-0 items-start gap-3"><span className="mt-0.5" style={{ color: expanded ? 'var(--accent-fg)' : 'var(--text-muted)' }}><Server size={15} /></span><div className="min-w-0"><div className="flex items-center gap-2"><span className="truncate text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{profile.name}</span>{profile.id === profiles[0]?.id && <ScopeBadge label="当前使用" />}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{profile.providerLabel} · {profile.models.length} 个模型 · {enabledCount} 个启用</div></div></div><ChevronRight size={14} className={`mt-0.5 shrink-0 transition ${expanded ? 'rotate-90' : ''}`} style={{ color: 'var(--text-muted)' }} /></button>{expanded && <div className="border-t px-3 pb-3 pt-3" style={{ borderColor: 'var(--border-subtle)' }}><SettingCard testId={profile.id === profiles[0]?.id ? 'settings-candidate-model-status' : undefined}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 items-start gap-2"><span className="mt-0.5 rounded-full p-1.5" style={{ background: status === 'success' ? 'color-mix(in srgb, var(--success) 12%, transparent)' : 'var(--bg-secondary)', color: status === 'success' ? 'var(--success)' : 'var(--accent-fg)' }}>{status === 'success' ? <Check size={14} /> : <Activity size={14} />}</span><div><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{status === 'success' ? '连接配置看起来可用' : status === 'error' ? '连接检查未通过' : '还没有验证连接'}</div><p className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{status === 'success' ? '这只是 Playground 的成功样张，不会真的发起请求。' : status === 'error' ? '样张失败态只用于确认反馈位置，不会暴露内部错误。' : '先完成入口、密钥和模型 ID，再做一次连接检查。'}</p></div></div><div className="flex shrink-0 gap-2"><button type="button" onClick={() => { const nextStatus = status === 'success' ? 'error' : 'success'; if (profile.id === profiles[0]?.id) onModelStatusChange(nextStatus); updateProfile(profile.id, (current) => ({ ...current, status: nextStatus })) }} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[10px] font-medium" style={{ borderColor: 'var(--border-color)', color: 'var(--text-primary)' }} data-testid="settings-candidate-model-test">{status === 'success' ? '模拟失败' : '模拟测试连接'}</button>{status === 'error' && <button type="button" onClick={() => { if (profile.id === profiles[0]?.id) onModelStatusChange('idle'); updateProfile(profile.id, (current) => ({ ...current, status: 'idle' })) }} className="rounded-[var(--radius-md)] px-3 py-1.5 text-[10px]" style={{ color: 'var(--accent-fg)' }}>重置</button>}</div></div></SettingCard><div className="mt-3 flex items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}><ListChecks size={14} style={{ color: 'var(--accent-fg)' }} />配置中的模型 <ScopeBadge label={`${profile.models.length} 个`} /></div><p className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>只展示已经加入这个配置的模型；不代表 Provider 自动提供了这些模型。</p></div><button type="button" onClick={() => { setAddingModelProfileId(profile.id); setModelDraftId(''); setModelDraftPurpose('auxiliary') }} className="inline-flex shrink-0 items-center gap-1 rounded-[var(--radius-md)] border px-2.5 py-1.5 text-[10px]" style={{ borderColor: 'var(--border-color)', color: 'var(--accent-fg)' }} data-testid={`settings-candidate-model-add-model-${profile.providerId}`}><Plus size={12} />添加模型</button></div>{profile.models.length === 0 && <div className="mt-3 rounded-[var(--radius-md)] border border-dashed p-3 text-center text-[10px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-muted)' }}>这个配置还没有加入模型</div>}{profile.models.length > 0 && <div className="mt-3 space-y-2">{profile.models.map((model) => <div key={model.id} className="flex flex-col gap-2 rounded-[var(--radius-md)] border px-3 py-2.5 sm:flex-row sm:items-center sm:justify-between" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="min-w-0"><div className="truncate font-mono text-[11px]" title={model.id} style={{ color: 'var(--text-primary)' }}>{model.id}</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>{model.enabled ? '已启用' : '已添加，暂未启用'}</div></div><div className="flex shrink-0 items-center gap-2"><select aria-label={`${model.id} 的用途`} value={model.purpose} onChange={(event) => updateModelPurpose(profile.id, model.id, event.target.value as ModelPurpose)} className="theme-input rounded-[var(--radius-sm)] border px-2 py-1 text-[10px] outline-none"><option value="primary">主对话</option><option value="auxiliary">辅助任务</option><option value="unused">暂不使用</option></select><button type="button" role="switch" aria-checked={model.enabled} aria-label={`启用 ${model.id}`} onClick={() => toggleModel(profile.id, model.id)} className="relative h-5 w-9 shrink-0 rounded-full" style={{ background: model.enabled ? 'var(--accent-emphasis)' : 'var(--bg-tertiary)' }}><span className="absolute top-0.5 h-4 w-4 rounded-full bg-white shadow-sm transition" style={{ left: model.enabled ? 'calc(100% - 1.125rem)' : '0.125rem' }} /></button></div></div>)}</div>}{addingModelProfileId === profile.id && <div className="mt-3 grid gap-2 rounded-[var(--radius-md)] border p-3 sm:grid-cols-[1fr_auto_auto]" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><input aria-label="追加模型 ID" value={modelDraftId} onChange={(event) => setModelDraftId(event.target.value)} placeholder="填写账户实际提供的模型 ID" className="theme-input rounded-[var(--radius-sm)] border px-2.5 py-2 text-[10px] outline-none" /><select aria-label="追加模型用途" value={modelDraftPurpose} onChange={(event) => setModelDraftPurpose(event.target.value as ModelPurpose)} className="theme-input rounded-[var(--radius-sm)] border px-2.5 py-2 text-[10px] outline-none"><option value="primary">主对话</option><option value="auxiliary">辅助任务</option><option value="unused">暂不使用</option></select><button type="button" onClick={() => finishAddModel(profile.id)} className="rounded-[var(--radius-sm)] border px-2.5 py-2 text-[10px]" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid={`settings-candidate-model-save-model-${profile.providerId}`}>加入配置</button></div>}<div className="mt-3 grid gap-2 text-[10px] sm:grid-cols-2"><div className="rounded-[var(--radius-sm)] border px-2.5 py-2" style={{ borderColor: 'var(--border-subtle)' }}><span style={{ color: 'var(--text-muted)' }}>Provider</span><div className="mt-1 truncate" title={profile.providerLabel} style={{ color: 'var(--text-secondary)' }}>{profile.providerLabel}</div></div><div className="rounded-[var(--radius-sm)] border px-2.5 py-2" style={{ borderColor: 'var(--border-subtle)' }}><span style={{ color: 'var(--text-muted)' }}>Base URL</span><div className="mt-1 truncate font-mono" title={profile.baseUrl} style={{ color: 'var(--text-secondary)' }}>{profile.baseUrl}</div></div></div></div>}</div> })}</div></SettingCard>}
    <SettingCard><button type="button" onClick={() => setShowAdvanced(!showAdvanced)} className="flex w-full items-center justify-between gap-3 text-left" aria-expanded={showAdvanced} data-testid="settings-candidate-model-advanced-toggle"><span className="flex items-center gap-2"><SlidersHorizontal size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>全局运行控制</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>所有模型配置共用的采样、上下文和预算控制。</span></span></span><ChevronRight size={14} className={`transition ${showAdvanced ? 'rotate-90' : ''}`} style={{ color: 'var(--text-muted)' }} /></button>{showAdvanced && <div className="mt-4 grid gap-3 border-t pt-4 sm:grid-cols-3" style={{ borderColor: 'var(--border-subtle)' }}>{[['Temperature', '0.7'], ['Top P', '1.0'], ['Max Tokens', '4096']].map(([label, value]) => <label key={label} className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>{label}<input aria-label={label} defaultValue={value} className="theme-input mt-1.5 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /></label>)}</div>}</SettingCard>
    <SettingCard testId="settings-candidate-model-budget"><div className="mb-3 flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>运行预算</h3><ScopeBadge label="全局" /></div><p className="mt-1 text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>给单次会话和每天的使用量设一个上限；填 0 表示不限制。</p></div><Gauge size={15} style={{ color: 'var(--accent-fg)' }} aria-hidden="true" /></div><div className="grid gap-3 sm:grid-cols-2"><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>会话预算<input type="number" min="0" inputMode="numeric" aria-label="会话预算" value={sessionBudget} onChange={(event) => setSessionBudget(event.target.value)} className="theme-input mt-1.5 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>{sessionBudget === '0' ? '当前：不限制' : `当前：${sessionBudget} 单位`}</span></label><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>每日预算<input type="number" min="0" inputMode="numeric" aria-label="每日预算" value={dailyBudget} onChange={(event) => setDailyBudget(event.target.value)} className="theme-input mt-1.5 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>{dailyBudget === '0' ? '当前：不限制' : `当前：${dailyBudget} 单位`}</span></label></div></SettingCard>
  </div>
}

function MemoryPage({ onOpenMemory }: { onOpenMemory?: () => void }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-memory"><CandidatePageHeader icon={<Brain size={14} />} title="记忆与相处" description="查看和管理伙伴记住的内容。" /><SettingCard><SettingRow scope="全局" label="记忆管理" description="查看用户记忆、伙伴记忆、我们之间和当前状态等内容。" icon={<Link2 size={15} />}><button type="button" onClick={onOpenMemory} className="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-[11px] transition" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} data-testid="settings-candidate-open-memory">打开记忆面板 <ChevronRight size={12} /></button></SettingRow></SettingCard></div>
}

function DataPage({ lastAction, onAction }: { lastAction: string; onAction: (action: string) => void }) {
  return <div className="space-y-4" data-testid="settings-candidate-section-data"><CandidatePageHeader icon={<Database size={14} />} title="数据与隐私" description="管理本地数据的迁移和备份，并明确哪些内容不会跟着备份文件离开设备。" /><SettingCard><div className="grid gap-2 sm:grid-cols-2"><button type="button" onClick={() => onAction('已模拟导出')} className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)' }} data-testid="settings-candidate-export"><span className="flex items-center gap-2"><Upload size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>导出数据</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>生成一份本地备份</span></span></span><ChevronRight size={14} style={{ color: 'var(--text-muted)' }} /></button><button type="button" onClick={() => onAction('已模拟导入')} className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3 text-left transition" style={{ borderColor: 'var(--border-subtle)' }} data-testid="settings-candidate-import"><span className="flex items-center gap-2"><Download size={15} style={{ color: 'var(--accent-fg)' }} /><span><span className="block text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>导入数据</span><span className="mt-1 block text-[10px]" style={{ color: 'var(--text-muted)' }}>从本地备份恢复</span></span></span><ChevronRight size={14} style={{ color: 'var(--text-muted)' }} /></button></div>{lastAction && <div className="mt-3 rounded-[var(--radius-md)] px-3 py-2 text-[11px]" role="status" style={{ background: 'var(--accent-subtle)', color: 'var(--accent-fg)' }}>{lastAction}（仅样张反馈）</div>}</SettingCard><SettingCard><div className="grid gap-4 sm:grid-cols-2"><div><div className="mb-2 flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}><Save size={14} style={{ color: 'var(--accent-fg)' }} />备份包含</div><ul className="space-y-1 text-[11px] leading-5" style={{ color: 'var(--text-secondary)' }}><li>会话与消息</li><li>记忆条目</li><li>普通模型与伙伴偏好</li></ul></div><div><div className="mb-2 flex items-center gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}><LockKeyhole size={14} style={{ color: 'var(--accent-fg)' }} />备份不包含</div><ul className="space-y-1 text-[11px] leading-5" style={{ color: 'var(--text-secondary)' }}><li>API Key 和 MCP 密钥</li><li>权限规则与执行模式</li><li>本机项目路径</li></ul></div></div></SettingCard></div>
}

function PermissionsPage({ mode, onModeChange }: { mode: string; onModeChange: (value: string) => void }) {
  const [showRules, setShowRules] = useState(false)
  const [ruleTarget, setRuleTarget] = useState('命令')
  const [ruleAction, setRuleAction] = useState('拒绝')
  const [rulePattern, setRulePattern] = useState('npm publish')
  const [savedRule, setSavedRule] = useState({ target: '命令', action: '拒绝', pattern: 'npm publish' })
  return <div className="space-y-4" data-testid="settings-candidate-section-permissions"><CandidatePageHeader icon={<ShieldCheck size={14} />} title="权限与自动化" description="让你决定 Agent 什么时候先问你、什么时候按计划推进；越高风险的能力越应该明确。" /><SettingCard><div className="mb-3"><h3 className="flex items-center gap-2 text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>默认审批方式<ScopeBadge label="全局" /></h3><p className="mt-1 text-[11px]" style={{ color: 'var(--text-muted)' }}>选择一个默认方式；遇到具体操作时，你仍然可以临时调整。</p></div><div className="grid gap-2 sm:grid-cols-3">{[['auto', '自动', '只在需要时确认'], ['confirm-all', '全部确认', '每次工具调用都先问'], ['plan-first', '先计划', '先看计划再执行']].map(([value, label, description]) => { const selected = mode === value; return <button key={value} type="button" aria-pressed={selected} onClick={() => onModeChange(value)} className="rounded-[var(--radius-md)] border p-3 text-left transition" style={{ borderColor: selected ? 'var(--accent)' : 'var(--border-subtle)', background: selected ? 'var(--accent-subtle)' : 'transparent' }}><div className="flex items-center justify-between gap-2 text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>{label}{selected && <Check size={13} style={{ color: 'var(--accent-fg)' }} />}</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>{description}</div></button> })}</div></SettingCard><SettingCard><button type="button" onClick={() => setShowRules(!showRules)} aria-expanded={showRules} className="flex w-full items-center justify-between gap-3 text-left" data-testid="settings-candidate-rules-toggle"><span className="flex min-w-0 items-center gap-2"><Settings2 size={15} style={{ color: 'var(--accent-fg)' }} /><span className="min-w-0"><span className="block text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>自定义权限规则</span><span className="mt-1 block truncate text-[10px]" style={{ color: 'var(--text-muted)' }}>自己指定某类操作：允许、需要确认，或直接拒绝。</span></span></span><ChevronRight size={14} className={`transition ${showRules ? 'rotate-90' : ''}`} style={{ color: 'var(--text-muted)' }} /></button>{showRules && <div className="mt-4 space-y-4 border-t pt-4" style={{ borderColor: 'var(--border-subtle)' }}><div><div className="mb-2 text-[11px] font-medium" style={{ color: 'var(--text-secondary)' }}>已有规则样张</div><div className="flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-2.5" style={{ borderColor: 'var(--border-subtle)' }}><div><div className="text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>{savedRule.action} · {savedRule.target}</div><div className="mt-1 font-mono text-[10px]" style={{ color: 'var(--text-muted)' }}>{savedRule.pattern}</div></div><span className="rounded-full px-2 py-0.5 text-[10px]" style={{ background: savedRule.action === '拒绝' ? 'color-mix(in srgb, var(--danger) 10%, transparent)' : 'var(--accent-subtle)', color: savedRule.action === '拒绝' ? 'var(--danger)' : 'var(--accent-fg)' }}>{savedRule.action}</span></div></div><div className="rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="mb-3"><div className="text-[11px] font-medium" style={{ color: 'var(--text-primary)' }}>新增一条规则</div><div className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>例如：拒绝发布命令；修改文件时，每次先问你。</div></div><div className="grid gap-3 sm:grid-cols-3"><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>操作类型<select aria-label="规则操作类型" value={ruleTarget} onChange={(event) => setRuleTarget(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none"><option>命令</option><option>修改文件</option><option>删除文件</option></select></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>处理方式<select aria-label="规则处理方式" value={ruleAction} onChange={(event) => setRuleAction(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none"><option>允许</option><option>需要确认</option><option>拒绝</option></select></label><label className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>匹配内容<input aria-label="规则匹配内容" value={rulePattern} onChange={(event) => setRulePattern(event.target.value)} className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-2.5 py-2 text-[11px] outline-none" placeholder="例如：npm publish" /></label></div><div className="mt-3 flex justify-end"><button type="button" onClick={() => setSavedRule({ target: ruleTarget, action: ruleAction, pattern: rulePattern || '未填写' })} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[10px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-save-rule">保存这条样张</button></div></div></div>}</SettingCard></div>
}

function ExtensionsPage() {
  const [skillsOpen, setSkillsOpen] = useState(false)
  const [skillsEnabled, setSkillsEnabled] = useState(true)
  const [skillsRunState, setSkillsRunState] = useState<'idle' | 'done'>('idle')
  const [mcpState, setMcpState] = useState<'empty' | 'adding' | 'connected'>('empty')
  return <div className="space-y-4" data-testid="settings-candidate-section-extensions"><CandidatePageHeader icon={<Plug size={14} />} title="扩展与工具" description="管理可以帮助伙伴完成特定任务的能力，以及需要额外连接的外部服务。" /><SettingCard><SettingRow scope="全局" label="Skills" description="按需启用能帮你完成特定任务的能力。" icon={<Wrench size={15} />}><button type="button" onClick={() => setSkillsOpen(!skillsOpen)} className="inline-flex items-center gap-1 rounded-full border px-3 py-1.5 text-[11px] transition" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} aria-expanded={skillsOpen} data-testid="settings-candidate-skills-toggle">{skillsOpen ? '收起样张' : '查看样张'} <ChevronRight size={12} className={`transition ${skillsOpen ? 'rotate-90' : ''}`} /></button></SettingRow>{skillsOpen && <div className="mt-4 space-y-3 rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="flex items-center justify-between gap-3"><div><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>文件整理助手</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>帮助你归纳文件、提取重点和整理结果。</div></div><CandidateSwitch checked={skillsEnabled} scope="全局" label="启用文件整理助手" description="" onChange={setSkillsEnabled} testId="settings-candidate-skills-enabled" /></div><div className="flex items-center justify-between gap-3 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><span className="text-[10px]" style={{ color: 'var(--text-muted)' }}>版本 <span>v1.2</span> · 已校验</span><button type="button" onClick={() => setSkillsRunState('done')} className="shrink-0 rounded-[var(--radius-md)] border px-2.5 py-1.5 text-[10px]" style={{ borderColor: 'var(--border-color)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-skills-run">{skillsRunState === 'done' ? '重新试跑' : '隔离试跑'}</button></div>{skillsRunState === 'done' && <div className="rounded-[var(--radius-sm)] px-2.5 py-2 text-[10px]" role="status" style={{ background: 'var(--accent-subtle)', color: 'var(--accent-fg)' }}>已生成隔离试跑结果</div>}</div>}</SettingCard><SettingCard testId="settings-candidate-mcp-card"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 gap-3"><span className="mt-0.5" style={{ color: 'var(--accent-fg)' }}><Link2 size={15} /></span><div><div className="flex items-center gap-2"><h3 className="text-[13px] font-medium" style={{ color: 'var(--text-primary)' }}>外部能力（MCP）</h3><ScopeBadge label="全局" /></div><p className="mt-1 text-[11px] leading-5" style={{ color: 'var(--text-muted)' }}>连接后，伙伴可以在你允许的范围内使用外部服务。</p></div></div>{mcpState === 'empty' && <button type="button" onClick={() => setMcpState('adding')} className="shrink-0 rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-secondary)' }} data-testid="settings-candidate-mcp-add">+ 添加</button>}</div>{mcpState === 'empty' && <div className="mt-4 rounded-[var(--radius-md)] border border-dashed p-4 text-center text-[11px]" style={{ borderColor: 'var(--border-color)', color: 'var(--text-muted)' }}>还没有外部能力连接</div>}{mcpState === 'adding' && <div className="mt-4 space-y-3 rounded-[var(--radius-md)] border p-3" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }} data-testid="settings-candidate-mcp-add-form"><div className="grid gap-3 sm:grid-cols-2"><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>显示名称<input aria-label="MCP 显示名称" placeholder="例如：文件工具" className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none" /></label><label className="text-[11px]" style={{ color: 'var(--text-secondary)' }}>连接方式<select aria-label="MCP 连接方式" className="theme-input mt-1 w-full rounded-[var(--radius-md)] border px-3 py-2 text-[12px] outline-none"><option>本地命令</option><option>远程地址</option></select></label></div><div className="flex items-center justify-between gap-3"><span className="text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>连接前会让你确认它需要访问的范围。</span><div className="flex gap-2"><button type="button" onClick={() => setMcpState('empty')} className="rounded-[var(--radius-md)] px-3 py-1.5 text-[11px]" style={{ color: 'var(--text-muted)' }}>取消</button><button type="button" onClick={() => setMcpState('connected')} className="rounded-[var(--radius-md)] border px-3 py-1.5 text-[11px] font-medium" style={{ borderColor: 'var(--accent)', color: 'var(--accent-fg)' }} data-testid="settings-candidate-mcp-connect">完成样张连接</button></div></div></div>}{mcpState === 'connected' && <div className="mt-4 flex items-center justify-between gap-3 rounded-[var(--radius-md)] border px-3 py-3" style={{ borderColor: 'color-mix(in srgb, var(--success) 40%, var(--border-color))', background: 'color-mix(in srgb, var(--success) 8%, transparent)' }}><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ background: 'var(--success)' }} /><div><div className="text-[12px] font-medium" style={{ color: 'var(--text-primary)' }}>文件工具 · 已连接</div><div className="mt-1 text-[10px]" style={{ color: 'var(--text-muted)' }}>样张状态 · 3 个能力</div></div></div><button type="button" onClick={() => setMcpState('empty')} className="rounded-[var(--radius-md)] px-2 py-1 text-[10px]" style={{ color: 'var(--danger)' }}>移除样张</button></div>}</SettingCard></div>
}

function AboutPage() {
  return <div className="space-y-4" data-testid="settings-candidate-section-about"><CandidatePageHeader icon={<CircleHelp size={14} />} title="关于 My Agent" description="查看版本、运行环境和本机数据位置。" /><SettingCard><div className="flex items-start gap-3"><Sparkles size={18} style={{ color: 'var(--companion-accent-warm)' }} /><div><div className="text-[15px] font-semibold" style={{ color: 'var(--text-primary)' }}>My Agent</div><p className="mt-1 text-[12px]" style={{ color: 'var(--text-muted)' }}>品牌标语待定</p></div></div><div className="mt-5 grid gap-3 text-[11px] sm:grid-cols-3" style={{ color: 'var(--text-secondary)' }}><div><div style={{ color: 'var(--text-muted)' }}>版本</div><div className="mt-1">0.1.0 · 开发中</div></div><div><div style={{ color: 'var(--text-muted)' }}>运行环境</div><div className="mt-1">Electron</div></div><div><div style={{ color: 'var(--text-muted)' }}>数据位置</div><div className="mt-1">本机存储</div></div></div></SettingCard></div>
}

export function SettingsExperienceCandidate({ companionDetail, initialSection, onOpenMemory, onOpenRoleShelf }: SettingsExperienceCandidateProps) {
  const [activeSection, setActiveSection] = useState<SettingsCandidateSection>(initialSection ?? 'appearance')
  const [activeTheme, setActiveTheme] = useState('mist')
  const [fontScale, setFontScale] = useState('md')
  const [momentTips, setMomentTips] = useState(true)
  const [proactiveGreeting, setProactiveGreeting] = useState(false)
  const [modelStatus, setModelStatus] = useState<'idle' | 'success' | 'error'>('idle')
  const [selectedProvider, setSelectedProvider] = useState('openai')
  const [expertise, setExpertise] = useState('auto')
  const [dataAction, setDataAction] = useState('')
  const [permissionMode, setPermissionMode] = useState('auto')

  useEffect(() => {
    // 场景从“记忆管理”返回普通设置时回到默认入口，避免保留上一场景的局部上下文。
    setActiveSection(initialSection ?? 'appearance')
  }, [initialSection])

  const activeSectionLabel = [...NAV_ITEMS, { id: 'about' as const, label: '关于 My Agent', icon: <CircleHelp size={15} /> }].find((item) => item.id === activeSection)?.label ?? '设置'

  return <div aria-label="设置候选版" className="flex min-h-[620px] w-full min-w-0 overflow-hidden rounded-[var(--radius-lg)] border" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-primary)' }} data-testid="settings-candidate"><aside className="hidden w-[198px] shrink-0 flex-col border-r px-3 py-4 md:flex" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }} data-testid="settings-nav"><div className="mb-5 px-2"><div className="text-[11px] font-semibold tracking-[0.18em]" style={{ color: 'var(--text-primary)' }}>设置</div><p className="mt-1 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>把真正需要决定的事放在眼前。</p></div><nav className="flex-1 space-y-5" aria-label="设置候选导航">{SETTINGS_CANDIDATE_NAV_GROUPS.map((group) => <div key={group.group}><div className="mb-1 px-2 text-[10px] font-semibold" style={{ color: 'var(--text-muted)' }}>{group.group}</div><div className="space-y-0.5">{group.items.map((item) => { const active = item.id === activeSection; return <button key={item.id} type="button" aria-current={active ? 'page' : undefined} aria-controls={`settings-candidate-panel-${item.id}`} title={item.label} onClick={() => setActiveSection(item.id)} className="settings-nav-item flex w-full items-center gap-2 px-2.5 py-2 text-left text-[12px] transition" style={{ color: active ? 'var(--text-primary)' : 'var(--text-secondary)', background: active ? 'var(--hover-overlay)' : undefined }} data-testid={`settings-candidate-nav-${item.id}`}><span style={{ color: active ? 'var(--accent-fg)' : 'var(--text-muted)' }}>{item.icon}</span><span className="min-w-0 truncate">{item.label}</span>{active && <ChevronRight size={12} className="ml-auto shrink-0" style={{ color: 'var(--text-muted)' }} />}</button> })}</div></div>)}</nav><div className="mt-5 border-t pt-3" style={{ borderColor: 'var(--border-subtle)' }}><button type="button" onClick={() => setActiveSection('about')} aria-current={activeSection === 'about' ? 'page' : undefined} aria-controls="settings-candidate-panel-about" title="关于 My Agent" className="settings-nav-item flex w-full items-center gap-2 px-2.5 py-2 text-left text-[12px]" style={{ color: activeSection === 'about' ? 'var(--text-primary)' : 'var(--text-secondary)', background: activeSection === 'about' ? 'var(--hover-overlay)' : undefined }} data-testid="settings-candidate-nav-about"><CircleHelp size={15} style={{ color: activeSection === 'about' ? 'var(--accent-fg)' : 'var(--text-muted)' }} />关于 My Agent</button><p className="mt-3 px-2 text-[10px] leading-4" style={{ color: 'var(--text-muted)' }}>Debug / Playground 使用应用全局入口，不在这里复制第二套导航。</p></div></aside><div className="flex min-w-0 flex-1 flex-col"><div className="min-w-0 overflow-hidden border-b px-3 py-2 md:hidden" style={{ borderColor: 'var(--border-subtle)', background: 'var(--bg-secondary)' }}><div className="flex min-w-0 w-full gap-1 overflow-x-auto" role="tablist" aria-label="设置候选导航" data-testid="settings-candidate-mobile-nav">{NAV_ITEMS.map((item) => { const active = item.id === activeSection; return <button key={item.id} type="button" role="tab" aria-selected={active} aria-controls={`settings-candidate-panel-${item.id}`} title={item.label} onClick={() => setActiveSection(item.id)} className="settings-option shrink-0 px-2.5 py-1.5 text-[10px]" data-selected={active ? 'true' : undefined}>{item.label}</button> })}<button type="button" role="tab" aria-selected={activeSection === 'about'} aria-controls="settings-candidate-panel-about" title="关于 My Agent" onClick={() => setActiveSection('about')} className="settings-option shrink-0 px-2.5 py-1.5 text-[10px]" data-selected={activeSection === 'about' ? 'true' : undefined}>关于</button></div></div><main className="scrollbar-thin min-h-0 flex-1 overflow-y-auto px-4 py-5 sm:px-6" data-testid="settings-main"><div key={activeSection} id={`settings-candidate-panel-${activeSection}`} role="tabpanel" aria-label={activeSectionLabel} className="view-transition mx-auto w-full max-w-3xl" data-testid="settings-candidate-content">{activeSection === 'appearance' && <AppearancePage activeTheme={activeTheme} fontScale={fontScale} onFontScaleChange={setFontScale} onThemeChange={setActiveTheme} />}{activeSection === 'companion' && (companionDetail ?? <CompanionPage expertise={expertise} momentTips={momentTips} onExpertiseChange={setExpertise} onOpenRoleShelf={onOpenRoleShelf} onMomentTipsChange={setMomentTips} onProactiveGreetingChange={setProactiveGreeting} proactiveGreeting={proactiveGreeting} />)}{activeSection === 'model' && <ModelPage modelStatus={modelStatus} onModelStatusChange={setModelStatus} selectedProvider={selectedProvider} onProviderChange={setSelectedProvider} />}{activeSection === 'memory' && <MemoryPage onOpenMemory={onOpenMemory} />}{activeSection === 'data' && <DataPage lastAction={dataAction} onAction={setDataAction} />}{activeSection === 'permissions' && <PermissionsPage mode={permissionMode} onModeChange={setPermissionMode} />}{activeSection === 'extensions' && <ExtensionsPage />}{activeSection === 'about' && <AboutPage />}</div></main></div></div>
}
